<template>
  <div class="campaigns-page">
    <div class="page-head"><div><div class="eyebrow">投放管理 / Meta</div><h2>广告系列</h2><p>统一查看和控制 Campaign、AdSet 与 Ad。</p></div><div><el-button :loading="loading" @click="refresh">刷新</el-button><el-button type="primary" @click="sync">同步 Meta</el-button></div></div>
    <el-alert v-if="taskNotice" :title="taskNotice" :type="taskNoticeType" :closable="true" @close="taskNotice = ''" show-icon style="margin-bottom: 12px" />
    <el-tabs v-model="activeTab" @tab-change="onTabChange">
      <el-tab-pane label="广告系列" name="campaigns"><el-card shadow="never"><div class="filters"><el-input v-model="keywordFilter" placeholder="搜索广告系列名称或 Meta ID" clearable @keyup.enter="loadCampaigns" /><el-input v-model="accountFilter" placeholder="广告账户 ID" clearable @keyup.enter="loadCampaigns" /><el-select v-model="statusFilter" placeholder="系统状态" clearable @change="loadCampaigns"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="已归档" value="ARCHIVED" /><el-option label="已删除" value="DELETED" /></el-select><el-button @click="loadCampaigns">筛选</el-button></div><el-table :data="campaigns" v-loading="loading"><el-table-column prop="name" label="广告系列" /><el-table-column prop="account_name" label="广告账户" show-overflow-tooltip /><el-table-column prop="meta_campaign_id" label="Meta ID" /><el-table-column prop="objective" label="目标" /><el-table-column label="Meta 状态"><template #default="{ row }"><el-tag size="small" :type="row.meta_status === 'ACTIVE' ? 'success' : 'warning'">{{ row.meta_status || '未同步' }}</el-tag></template></el-table-column><el-table-column label="系统状态"><template #default="{ row }"><el-tag size="small" :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row)">详情</el-button><el-button link type="primary" @click="openAdsets(row)">广告组</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="warning" @click="changeStatus(row)">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="danger" @click="archive(row)">归档</el-button><el-button v-if="row.status !== 'DELETED'" link type="danger" @click="removePublished(row)">移除</el-button><el-button v-if="['ARCHIVED','DELETED'].includes(row.status)" link type="success" @click="restore(row)">恢复</el-button></template></el-table-column></el-table><el-empty v-if="!loading && !campaigns.length" description="暂无广告系列，请先完成批量投放" /></el-card></el-tab-pane>
      <el-tab-pane label="广告组" name="adsets"><el-card shadow="never"><div class="sub-head"><div><el-select v-model="selectedCampaignId" placeholder="选择广告系列" filterable clearable @change="selectCampaign" style="width:320px"><el-option v-for="item in campaigns" :key="item.id" :label="`${item.name} · ${item.account_name || item.meta_campaign_id}`" :value="item.id" /></el-select><el-select v-model="adsetStatusFilter" placeholder="状态" clearable @change="selectedCampaignId && loadAdsets(selectedCampaignId)" style="width:120px"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="归档" value="ARCHIVED" /><el-option label="已移除" value="DELETED" /></el-select></div><el-button link @click="activeTab = 'campaigns'">返回广告系列</el-button></div><el-table :data="adsets" v-loading="subLoading"><el-table-column prop="name" label="广告组" /><el-table-column prop="meta_adset_id" label="Meta ID" /><el-table-column prop="optimization_goal" label="优化目标" /><el-table-column prop="daily_budget" label="日预算" /><el-table-column label="状态"><template #default="{ row }"><el-tag size="small" :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status || '未知' }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click="openAds(row)">查看广告</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="warning" @click="changeStatus(row)">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="danger" @click="archive(row)">归档</el-button><el-button v-if="row.status !== 'DELETED'" link type="danger" @click="removePublished(row)">移除</el-button><el-button v-if="['ARCHIVED','DELETED'].includes(row.status)" link type="success" @click="restore(row)">恢复</el-button></template></el-table-column></el-table><el-empty v-if="!subLoading && selectedCampaignId && !adsets.length" description="该广告系列暂无广告组" /></el-card></el-tab-pane>
      <el-tab-pane label="广告" name="ads"><el-card shadow="never"><div class="sub-head"><div><el-select v-model="selectedAdsetId" placeholder="选择广告组" filterable clearable @change="selectAdset" style="width:320px"><el-option v-for="item in adsets" :key="item.id" :label="`${item.name} · ${item.meta_adset_id}`" :value="item.id" /></el-select><el-select v-model="adStatusFilter" placeholder="状态" clearable @change="selectedAdsetId && loadAds(selectedAdsetId)" style="width:120px"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="归档" value="ARCHIVED" /><el-option label="已移除" value="DELETED" /></el-select></div><el-button link @click="activeTab = 'adsets'">返回广告组</el-button></div><el-table :data="ads" v-loading="subLoading"><el-table-column prop="name" label="广告" /><el-table-column prop="meta_ad_id" label="Meta ID" /><el-table-column prop="effective_status" label="Meta 状态" /><el-table-column prop="status" label="系统状态" /><el-table-column label="操作"><template #default="{ row }"><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="warning" @click="changeStatus(row)">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="danger" @click="archive(row)">归档</el-button><el-button v-if="row.status !== 'DELETED'" link type="danger" @click="removePublished(row)">移除</el-button><el-button v-if="['ARCHIVED','DELETED'].includes(row.status)" link type="success" @click="restore(row)">恢复</el-button></template></el-table-column></el-table><el-empty v-if="!subLoading && selectedAdsetId && !ads.length" description="该广告组暂无广告" /></el-card></el-tab-pane>
      <el-tab-pane label="异步任务" name="jobs"><el-card shadow="never"><el-table :data="jobs" v-loading="jobLoading"><el-table-column prop="id" label="投放任务 ID" /><el-table-column prop="action_type" label="动作" /><el-table-column prop="status" label="状态" /><el-table-column prop="created_at" label="创建时间" /></el-table><el-divider /><div class="sub-head">Meta 操作任务</div><el-table :data="metaTasks" size="small"><el-table-column prop="task_id" label="Celery Task ID" show-overflow-tooltip /><el-table-column prop="task_type" label="类型" /><el-table-column prop="object_type" label="对象" /><el-table-column prop="status" label="状态" /><el-table-column prop="created_at" label="提交时间" /></el-table><el-divider /><div class="sub-head">启停 / 归档 / 移除记录</div><el-table :data="deliveryActions" size="small"><el-table-column prop="action" label="动作" width="100" /><el-table-column prop="object_type" label="对象类型" width="110" /><el-table-column prop="object_id" label="对象 ID" show-overflow-tooltip /><el-table-column prop="status" label="状态" width="110" /><el-table-column prop="desired_status" label="目标状态" width="110" /><el-table-column prop="created_at" label="提交时间" /><el-table-column label="操作" width="80"><template #default="{ row }"><el-button v-if="row.status === 'FAILED'" link type="warning" @click="retryAction(row)">重试</el-button></template></el-table-column></el-table></el-card></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="detailVisible" title="投放详情" width="760px"><div v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="广告系列">{{ detail.campaign?.name }}</el-descriptions-item><el-descriptions-item label="Meta Campaign ID">{{ detail.campaign?.meta_campaign_id }}</el-descriptions-item><el-descriptions-item label="广告账户">{{ detail.account?.account_name || detail.campaign?.ad_account_id }}</el-descriptions-item><el-descriptions-item label="发布状态">{{ detail.campaign?.status }}</el-descriptions-item><el-descriptions-item label="推广目标">{{ detail.template?.objective }}</el-descriptions-item><el-descriptions-item label="投放形式">{{ detail.creative_config?.creative_format === 'CAROUSEL' ? '多图片轮播' : '多素材多个广告' }}</el-descriptions-item><el-descriptions-item label="发布任务">{{ detail.job_item?.job_id || '-' }}</el-descriptions-item></el-descriptions><el-alert v-if="detail.job_item?.response_payload?.cleanup_attempted" :type="detail.job_item.response_payload.cleanup_failed ? 'error' : 'success'" :title="detail.job_item.response_payload.cleanup_failed ? '发布失败，部分 Meta 对象未清理' : '发布失败，Meta 对象已自动回滚'" show-icon style="margin-top:12px"><template #default><span v-if="detail.job_item.response_payload.cleanup_failed">待人工清理：{{ detail.job_item.response_payload.cleanup_object_ids?.join(', ') }}</span><span v-else>本次创建的 Campaign、AdSet、Ad 已执行逆序清理。</span></template></el-alert><h4>广告组与广告</h4><el-table :data="detail.adsets || []" size="small"><el-table-column prop="name" label="广告组" /><el-table-column prop="meta_adset_id" label="Meta AdSet ID" /><el-table-column label="广告"><template #default="{ row }">{{ (row.ads || []).map((item: any) => item.meta_ad_id).join(', ') || '-' }}</template></el-table-column></el-table><h4>创意与落地页</h4><pre class="detail-json">{{ JSON.stringify(detail.creative_config?.creative_format === 'CAROUSEL' ? detail.creative_config?.carousel_cards || [] : detail.creative_config?.creatives || [], null, 2) }}</pre></div></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { campaignsApi, type DeliveryAction, type MetaAd, type MetaAdSet, type MetaCampaign } from '@/api/campaigns'
import { jobsApi, type CampaignJob } from '@/api/jobs'
const activeTab = ref('campaigns'); const loading = ref(false); const subLoading = ref(false); const jobLoading = ref(false)
const campaigns = ref<MetaCampaign[]>([]); const adsets = ref<MetaAdSet[]>([]); const ads = ref<MetaAd[]>([]); const jobs = ref<CampaignJob[]>([]); const metaTasks = ref<any[]>([]); const deliveryActions = ref<DeliveryAction[]>([])
const selectedCampaign = ref<MetaCampaign | null>(null); const selectedAdset = ref<MetaAdSet | null>(null)
const selectedCampaignId = ref(''); const selectedAdsetId = ref(''); const adsetStatusFilter = ref(''); const adStatusFilter = ref('')
const detailVisible = ref(false); const detail = ref<any>(null)
const accountFilter = ref(''); const statusFilter = ref('')
const keywordFilter = ref('')
const taskNotice = ref(''); const taskNoticeType = ref<'info' | 'success' | 'warning' | 'error'>('info')
let refreshTimer: ReturnType<typeof setTimeout> | undefined
let taskTimer: ReturnType<typeof setTimeout> | undefined
async function loadCampaigns() { loading.value = true; try { const { data } = await campaignsApi.list({ keyword: keywordFilter.value || undefined, ad_account_id: accountFilter.value || undefined, status: statusFilter.value || undefined }); campaigns.value = data } finally { loading.value = false } }
async function showDetail(row: MetaCampaign) { const { data } = await campaignsApi.detail(row.id); detail.value = data; detailVisible.value = true }
async function openAdsets(row: MetaCampaign) { selectedCampaign.value = row; selectedCampaignId.value = row.id; selectedAdset.value = null; selectedAdsetId.value = ''; ads.value = []; activeTab.value = 'adsets'; await loadAdsets(row.id) }
async function loadAdsets(id: string) { subLoading.value = true; try { const { data } = await campaignsApi.adsets(id, adsetStatusFilter.value || undefined); adsets.value = data } catch (error: any) { adsets.value = []; ElMessage.error(error?.response?.data?.detail || '加载广告组失败') } finally { subLoading.value = false } }
async function selectCampaign(id?: string) { const row = campaigns.value.find(item => item.id === id); selectedCampaign.value = row || null; selectedAdset.value = null; selectedAdsetId.value = ''; ads.value = []; if (id) await loadAdsets(id); else adsets.value = [] }
async function openAds(row: MetaAdSet) { selectedAdset.value = row; selectedAdsetId.value = row.id; activeTab.value = 'ads'; await loadAds(row.id) }
async function loadAds(id: string) { subLoading.value = true; try { const { data } = await campaignsApi.ads(id, adStatusFilter.value || undefined); ads.value = data } catch (error: any) { ads.value = []; ElMessage.error(error?.response?.data?.detail || '加载广告失败') } finally { subLoading.value = false } }
async function selectAdset(id?: string) { const row = adsets.value.find(item => item.id === id); selectedAdset.value = row || null; if (id) await loadAds(id); else ads.value = [] }
function watchTasks(taskIds: string[]) { if (!taskIds.length) return; if (taskTimer) clearTimeout(taskTimer); let round = 0; const poll = async () => { const statuses = await Promise.all(taskIds.map(id => campaignsApi.taskStatus(id).then(({ data }) => data).catch(() => ({ task_id: id, state: 'UNKNOWN' })))); const finished = statuses.filter(item => ['SUCCESS', 'FAILURE', 'REVOKED'].includes(item.state)); const failed = statuses.filter(item => ['FAILURE', 'REVOKED'].includes(item.state)); const partial = statuses.filter(item => item.result?.status === 'partial_success'); const errorCount = statuses.reduce((sum, item) => sum + Number(item.result?.error_count || 0), 0); taskNoticeType.value = failed.length ? 'error' : partial.length || errorCount ? 'warning' : finished.length === statuses.length ? 'success' : 'info'; taskNotice.value = finished.length === statuses.length ? (failed.length ? `任务完成：${failed.length} 个失败` : partial.length || errorCount ? `任务完成，但有 ${errorCount || partial.length} 项同步异常` : 'Meta 任务已完成，页面状态已刷新') : `Meta 任务执行中：${finished.length}/${statuses.length}`; if (finished.length === statuses.length || round++ >= 30) { await refresh(); return } taskTimer = setTimeout(poll, 2000) }; poll() }
async function sync() { try { const { data } = await campaignsApi.sync(campaigns.value.map(row => row.id)); ElMessage.success('同步任务已提交：' + (data.task_ids?.length || 0) + ' 个账户'); taskNotice.value = 'Meta 同步任务已提交'; activeTab.value = 'jobs'; await loadJobs(); watchTasks(data.task_ids || []) } catch {} }
function scheduleRefresh(attempt = 0) { if (refreshTimer) clearTimeout(refreshTimer); if (attempt >= 3) return; refreshTimer = setTimeout(async () => { try { if (activeTab.value === 'campaigns') await loadCampaigns(); else if (activeTab.value === 'adsets' && selectedCampaign.value) { const { data } = await campaignsApi.adsets(selectedCampaign.value.id, adsetStatusFilter.value || undefined); adsets.value = data } else if (activeTab.value === 'ads' && selectedAdset.value) { const { data } = await campaignsApi.ads(selectedAdset.value.id, adStatusFilter.value || undefined); ads.value = data } } finally { scheduleRefresh(attempt + 1) } }, 2000) }
function actionKey(action: string, id: string) { return `${action}:${id}:${Date.now()}:${Math.random().toString(16).slice(2)}` }
async function changeStatus(row: MetaCampaign | MetaAdSet | MetaAd) { const action = row.status === 'ACTIVE' ? 'PAUSE' : 'ENABLE'; try { await ElMessageBox.confirm('确认操作「' + row.name + '」？', '确认操作', { type: 'warning' }); const { data } = await campaignsApi.action({ action, ids: [row.id], idempotency_key: actionKey(action, row.id) }); ElMessage.success('异步任务已提交：' + ((data.task_ids || []).length || data.job_id || '处理中')); taskNotice.value = '状态变更任务已提交'; watchTasks(data.task_ids || []); scheduleRefresh() } catch {} }
async function archive(row: MetaCampaign | MetaAdSet | MetaAd) { try { await ElMessageBox.confirm('归档后默认列表将隐藏该对象，Meta 侧会先暂停投放。确认归档「' + row.name + '」？', '确认归档', { type: 'warning' }); const { data } = await campaignsApi.action({ action: 'ARCHIVE', ids: [row.id], idempotency_key: actionKey('ARCHIVE', row.id) }); ElMessage.success('归档任务已提交'); taskNotice.value = '归档任务已提交'; watchTasks(data.task_ids || []); scheduleRefresh() } catch {} }
async function removePublished(row: MetaCampaign | MetaAdSet | MetaAd) { try { await ElMessageBox.confirm('移除仅隐藏本地发布记录，Meta 侧会先暂停投放，不执行硬删除。确认移除「' + row.name + '」？', '确认移除', { type: 'warning', confirmButtonText: '确认移除' }); const { data } = await campaignsApi.action({ action: 'DELETE', ids: [row.id], idempotency_key: actionKey('DELETE', row.id) }); ElMessage.success('移除任务已提交'); taskNotice.value = '移除任务已提交（Meta 侧暂停）'; watchTasks(data.task_ids || []); scheduleRefresh() } catch {} }
async function restore(row: MetaCampaign | MetaAdSet | MetaAd) { try { await ElMessageBox.confirm('恢复只恢复本地可见性并保持 Meta 暂停，不会立即重新花费。确认恢复「' + row.name + '」？', '确认恢复', { type: 'warning' }); const { data } = await campaignsApi.action({ action: 'RESTORE', ids: [row.id], idempotency_key: actionKey('RESTORE', row.id) }); ElMessage.success('恢复任务已提交'); taskNotice.value = '恢复任务已提交（Meta 侧保持暂停）'; watchTasks(data.task_ids || []); scheduleRefresh() } catch {} }
async function retryAction(row: DeliveryAction) { try { await ElMessageBox.confirm('该操作上次执行失败，确认重新提交？原失败记录会保留。', '确认重试', { type: 'warning' }); const { data } = await campaignsApi.retryDeliveryAction(row.id); ElMessage.success('重试任务已提交'); taskNotice.value = '失败操作已重新提交'; watchTasks(data.task_id ? [data.task_id] : []); await loadJobs() } catch {} }
async function loadJobs() { jobLoading.value = true; try { const [{ data: jobData }, { data: taskData }, { data: actionData }] = await Promise.all([jobsApi.list({ limit: 50 }), campaignsApi.taskRecords(50), campaignsApi.deliveryActions(50)]); jobs.value = jobData; metaTasks.value = taskData; deliveryActions.value = actionData } finally { jobLoading.value = false } }
async function refresh() { await loadCampaigns(); await loadJobs() }
async function onTabChange(tab: string | number) { if (tab === 'jobs') await loadJobs(); else if (tab === 'adsets' && !selectedCampaignId.value) adsets.value = []; else if (tab === 'ads' && !selectedAdsetId.value) ads.value = [] }
onMounted(refresh)
onBeforeUnmount(() => { if (refreshTimer) clearTimeout(refreshTimer); if (taskTimer) clearTimeout(taskTimer) })
</script>
<style scoped>.campaigns-page{padding:4px}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.eyebrow{color:#829ab1;font-size:12px}.page-head h2{margin:6px 0;color:#102a43}.page-head p{margin:0;color:#627d98;font-size:13px}.filters{display:flex;gap:8px;margin-bottom:12px}.filters .el-input{width:220px}.filters .el-select{width:150px}.sub-head{display:flex;justify-content:space-between;margin-bottom:12px;color:#52606d}.detail-json{max-height:240px;overflow:auto;background:#f5f7fa;padding:12px;border-radius:4px;font-size:12px;white-space:pre-wrap;word-break:break-all}</style>
